package de.tum.cit.aet.sorting;

import java.util.Date;
import java.util.Objects;

public class Book implements Comparable<Book> {
    private String title;
    private Date returnDate;

    public Book(String title, Date returnDate) {
        this.title = title;
        this.returnDate = returnDate;
    }

    public String getTitle() { return title; }
    public Date getReturnDate() { return returnDate; }

    @Override
    public int compareTo(Book o) {
        return this.returnDate.compareTo(o.returnDate);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Book book = (Book) o;
        return Objects.equals(title, book.title) && Objects.equals(returnDate, book.returnDate);
    }

    @Override
    public int hashCode() {
        return Objects.hash(title, returnDate);
    }

    @Override
    public String toString() {
        return "Book{" + "title='" + title + '\'' + ", returnDate=" + returnDate + '}';
    }
}

